package com.example.events;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="events") public class Event { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String title; @Column(nullable=false,length=3000) public String description; public String category; @Column(nullable=false) public LocalDateTime dateTime; @Column(nullable=false) public LocalDateTime registrationDeadline; @Column(nullable=false) public String venue; @Column(nullable=false,precision=10,scale=2) public BigDecimal price=BigDecimal.ZERO; @Column(nullable=false) public int capacity; @Column(nullable=false) public int availableSeats; @Column(nullable=false) public String status="PUBLISHED"; public Event(){} }
